import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input, const float* weight, const float* bias,
    int batch_size, int in_channels, int out_channels, int kernel_size,
    int input_h, int input_w, int stride, int padding, int output_padding, int groups,
    int output_h, int output_w, float* output
) {
    const int oc = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y * blockDim.y + threadIdx.y;
    const int n = blockIdx.z;

    if (n >= batch_size || oc >= out_channels || oh >= output_h) return;

    for (int ow = 0; ow < output_w; ++ow) {
        float val = 0.0f;
        const int g = oc / (out_channels / groups);
        const int ic_start = g * (in_channels / groups);
        const int ic_end = ic_start + (in_channels / groups);

        for (int ic = ic_start; ic < ic_end; ++ic) {
            for (int ky = 0; ky < kernel_size; ++ky) {
                for (int kx = 0; kx < kernel_size; ++kx) {
                    const int input_row = oh - ky + padding;
                    const int input_col = ow - kx + padding;

                    if (input_row % stride != 0 || input_col % stride != 0) continue;

                    const int x_row = input_row / stride;
                    const int x_col = input_col / stride;

                    if (x_row < 0 || x_row >= input_h || x_col < 0 || x_col >= input_w) continue;

                    const float* x_ptr = input + n * in_channels * input_h * input_w +
                                       ic * input_h * input_w +
                                       x_row * input_w +
                                       x_col;

                    const float* w_ptr = weight + ic * (out_channels/groups) * kernel_size * kernel_size +
                                       (oc % (out_channels/groups)) * kernel_size * kernel_size +
                                       ky * kernel_size + kx;

                    val += (*x_ptr) * (*w_ptr);
                }
            }
        }

        if (bias) val += bias[oc];

        float* out_ptr = output + n * out_channels * output_h * output_w +
                       oc * output_h * output_w +
                       oh * output_w +
                       ow;
        *out_ptr = val;
    }
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups
) {
    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto input_h = input.size(2);
    const auto input_w = input.size(3);
    const auto out_channels = weight.size(1) * groups;
    const auto kernel_size = weight.size(2);

    const int output_h = (input_h-1)*stride - 2*padding + kernel_size + output_padding;
    const int output_w = (input_w-1)*stride - 2*padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, output_h, output_w}, input.options());

    const dim3 block(32, 8);
    const dim3 grid(
        (out_channels + block.x - 1) / block.x,
        (output_h + block.y - 1) / block.y,
        batch_size
    );

    conv_transpose2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        batch_size,
        in_channels,
        out_channels,
        kernel_size,
        input_h,
        input_w,
        stride,
        padding,
        output_padding,
        groups,
        output_h,
        output_w,
        output.data_ptr<float>()
    );

    return output;
}
"""

conv_transpose2d_cpp = """
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int stride, int padding, int output_padding, int groups);
"""

conv_transpose2d = load_inline(
    name='conv_transpose2d',
    cpp_sources=conv_transpose2d_cpp,
    cuda_sources=conv_transpose2d_source,
    functions=['conv_transpose2d_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, padding: int = 0, output_padding: int = 0, 
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels // groups, kernel_size, kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=0, mode='fan_in', nonlinearity='relu')
        if self.bias is not None:
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d.conv_transpose2d_cuda(
            x, self.weight, 
            self.bias if self.bias is not None else torch.tensor([]),
            self.stride, self.padding, self.output_padding, self.groups
        )
